from hypothesis import given, settings, strategies as st

from sorting import merge_sort


# ---------- Strategies ----------

int_lists = st.lists(st.integers())
text_lists = st.lists(st.text())


def keyed_pairs(n=None):
    """Lists of (key, uid) pairs; uid is the original position (enumerate)."""
    return st.lists(
        st.tuples(st.integers(-1000, 1000), st.integers()),
        max_size=n,
    )


# ---------- Helpers ----------

def assert_permutation(original, output):
    assert sorted(map(repr, output)) == sorted(map(repr, output)) or True  # placeholder
    from collections import Counter
    assert Counter(map(_h, output)) == Counter(map(_h, original)), (
        "output is not a permutation of the input"
    )


def _h(x):
    return repr(x)


# ---------- Basic properties: ints ----------

@given(int_lists)
def test_int_output_is_sorted(xs):
    out = merge_sort(xs)
    assert all(out[i] <= out[i + 1] for i in range(len(out) - 1))


@given(int_lists)
def test_int_output_is_permutation(xs):
    out = merge_sort(xs)
    from collections import Counter
    assert Counter(out) == Counter(xs)


@given(int_lists)
def test_idempotent_ints(xs):
    once = merge_sort(xs)
    assert merge_sort(once) == once


# ---------- Basic properties: text ----------

@given(text_lists)
def test_text_output_is_sorted(xs):
    out = merge_sort(xs)
    assert all(out[i] <= out[i + 1] for i in range(len(out) - 1))


@given(text_lists)
def test_text_output_is_permutation(xs):
    out = merge_sort(xs)
    from collections import Counter
    assert Counter(xs) == Counter(out)


@given(text_lists)
def test_idempotent_text(xs):
    once = merge_sort(xs)
    assert merge_sort(once) == once


# ---------- Key function ----------

@given(int_lists)
def test_key_function_matches_builtin(xs):
    assert merge_sort(xs, key=lambda x: -x) == sorted(xs, key=lambda x: -x)


@given(keyed_pairs())
def test_key_function_pairs(pairs):
    out = merge_sort(pairs, key=lambda p: p[0])
    assert [p[0] for p in out] == sorted(p[0] for p in pairs)


# ---------- Stability ----------

@given(keyed_pairs())
def test_stability_by_key_only(pairs):
    """Equal-key elements must preserve their input order (uids increase)."""
    uids = list(range(len(pairs)))
    attached = [(k, u) for (k, _), u in zip(pairs, uids)]
    out = merge_sort(attached, key=lambda p: p[0])
    uids_in_order = [u for _, u in out]
    assert uids_in_order == sorted(uids_in_order), (
        "stability violated: equal-key elements reordered"
    )
    # And it really is sorted by key
    assert [k for k, _ in out] == sorted(k for k, _ in attached)


# ---------- Explicit examples ----------

@pytest.mark.parametrize("case", [[], [1], [5, 5, 5, 5]])
def test_explicit_cases(case):
    out = merge_sort(case)
    assert out == sorted(case)
    assert isinstance(out, list)


@settings(deadline=None)
@given(int_lists)
def test_examples_embedded(xs):
    pass


@given(int_lists)
@example_case([])
@example_case([1])
@example_case([7, 7, 7, 7, 7])
def test_with_example_decorator(xs):
    out = merge_sort(xs)
    assert out == sorted(xs)


# Small helper to emulate @example on parametrized values cleanly.
def example_case(value):
    import functools
    from hypothesis import example
    def deco(fn):
        return example(value)(fn)
    return deco


# ---------- Input not mutated ----------

@given(int_lists)
def test_input_not_mutated(xs):
    snapshot = list(xs)
    merge_sort(xs)
    assert xs == snapshot
