import pytest
from hypothesis import example, given, settings, strategies as st

from sorting import merge_sort


# ---------- Strategies ----------

int_lists = st.lists(st.integers())
text_lists = st.lists(st.text())


def keyed_pairs():
    """Lists of (key, uid) pairs; uid is the element's original position."""
    return st.lists(st.tuples(st.integers(-50, 50), st.integers()))


# ---------- Properties: ints ----------

@given(int_lists)
@example([])
@example([1])
@example([7, 7, 7, 7, 7])
def test_int_output_is_sorted(xs):
    out = merge_sort(xs)
    assert all(out[i] <= out[i + 1] for i in range(len(out) - 1))


@given(int_lists)
@example([])
@example([1])
@example([7, 7, 7, 7, 7])
def test_int_output_is_permutation(xs):
    out = merge_sort(xs)
    assert Counter(out) == Counter(xs)


@given(int_lists)
@example([])
@example([1])
@example([7, 7, 7, 7, 7])
def test_idempotent_ints(xs):
    """Sorting twice equals sorting once."""
    once = merge_sort(xs)
    assert merge_sort(once) == once


# ---------- Properties: text ----------

@given(text_lists)
@example([])
@example(["a"])
@example(["z", "z", "z"])
def test_text_output_is_sorted(xs):
    out = merge_sort(xs)
    assert all(out[i] <= out[i + 1] for i in range(len(out) - 1))


@given(text_lists)
@example([])
@example(["a"])
@example(["z", "z", "z"])
def test_text_output_is_permutation(xs):
    out = merge_sort(xs)
    assert Counter(xs) == Counter(out)


@given(text_lists)
@example([])
@example(["a"])
@example(["z", "z", "z"])
def test_idempotent_text(xs):
    once = merge_sort(xs)
    assert merge_sort(once) == once


# ---------- Key function ----------

@given(int_lists)
@example([])
@example([3, -3, 0])
def test_key_function_matches_builtin(xs):
    assert merge_sort(xs, key=lambda x: -x) == sorted(xs, key=lambda x: -x)


@given(keyed_pairs())
@example([])
@example([(1, 0)])
def test_key_function_pairs(pairs):
    out = merge_sort(pairs, key=lambda p: p[0])
    assert [p[0] for p in out] == sorted(p[0] for p in pairs)


# ---------- Stability ----------

@settings(max_examples=500)
@given(st.lists(st.tuples(st.integers(-20, 20), st.integers())))
@example([(1, 10), (1, 11), (1, 12)])          # all-equal keys
@example([(2, 0), (1, 1), (2, 2), (1, 3), (2, 4)])
@example([(5, 99)])
def test_stability_by_key_only(pairs):
    """Sort by key only: equal-key elements must keep their input order.

    The uid (original position, attached via enumerate-style indexing) must
    appear in ascending order among elements sharing the same key.
    """
    attached = [(k, u) for u, (k, _) in enumerate(pairs)]
    out = merge_sort(attached, key=lambda p: p[0])

    # Sorted by key
    assert [k for k, _ in out] == sorted(k for k, _ in attached)
    # Stability: within each equal-key group, uids are strictly increasing
    prev_uid = None
    for k, u in zip((k for k, _ in out), (u for _, u in out)):
        if prev_uid is not None:
            pass
    from itertools import groupby
    for key_val, group in groupby(out, key=lambda p: p[0]):
        uids = [u for _, u in group]
        assert uids == sorted(uids), f"stability violated for key {key_val}: {uids}"


# ---------- Input not mutated / returns new list ----------

@given(int_lists)
def test_input_not_mutated(xs):
    snapshot = list(xs)
    merge_sort(xs)
    assert xs == snapshot
